ms_output.rate_norm_t_s = 0.0;
ms_output.field_energy_t2 = 0.0;

/* Validate configuration: binary enable, positive finite dt/max_slew, max_rejects in 1..10 */
if ((ms_input.enable != 0) && (ms_input.enable != 1)) {
    ms_state.initialized = 0;
    ms_output.mode = MS_FAULT;
    ms_output.rejects = ms_state.rejects;
    return;
}
if ((!isfinite(ms_input.dt_s)) || (ms_input.dt_s <= 0.0)) {
    ms_state.initialized = 0;
    ms_output.mode = MS_FAULT;
    ms_output.rejects = ms_state.rejects;
    return;
}
if ((!isfinite(ms_config.max_slew_t_s)) || (ms_config.max_slew_t_s <= 0.0)) {
    ms_state.initialized = 0;
    ms_output.mode = MS_FAULT;
    ms_output.rejects = ms_state.rejects;
    return;
}
if ((ms_config.max_rejects < 1U) || (ms_config.max_rejects > 10U)) {
    ms_state.initialized = 0;
    ms_output.mode = MS_FAULT;
    ms_output.rejects = ms_state.rejects;
    return;
}

/* Disabled: clear history and rejects, EMPTY zero */
if (ms_input.enable == 0) {
    ms_state.initialized = 0;
    ms_state.rejects = 0U;
    ms_state.previous_field_t = (adcs_vec3_t){0.0, 0.0, 0.0};
    ms_output.mode = MS_EMPTY;
    ms_output.rejects = 0U;
    return;
}

/* Invalid input (NULL, nonfinite, degenerate zero) latches FAULT, do not accept field */
if ((ms_input.field_body_t == NULL) || (!adcs_is_finite_vec3(ms_input.field_body_t))) {
    ms_output.mode = MS_FAULT;
    ms_output.rejects = ms_state.rejects;
    return;
}

/* field_energy_t2 = field dot field for every valid sample */
{
    double energy = adcs_vec3_dot(ms_input.field_body_t, ms_input.field_body_t);

    if (!isfinite(energy) || (energy <= ADCS_EPS_NORM * ADCS_EPS_NORM)) {
        ms_output.mode = MS_FAULT;
        ms_output.rejects = ms_state.rejects;
        return;
    }
    ms_output.field_energy_t2 = energy;
}

/* First valid field: TRACK, zero rate, store field */
if (!ms_state.initialized) {
    ms_state.previous_field_t = *ms_input.field_body_t;
    ms_state.initialized = 1;
    ms_state.rejects = 0U;
    ms_output.mode = MS_TRACK;
    ms_output.rejects = 0U;
    ms_output.accepted_field_t = *ms_input.field_body_t;
    ms_output.rate_t_s = (adcs_vec3_t){0.0, 0.0, 0.0};
    ms_output.rate_norm_t_s = 0.0;
    return;
}

/* Later samples: rate = (current - previous) / dt via linked subtraction and scaling */
{
    adcs_vec3_t delta = adcs_vec3_sub(ms_input.field_body_t, &ms_state.previous_field_t);
    adcs_vec3_t rate = adcs_vec3_scale(&delta, 1.0 / ms_input.dt_s);
    double rate_norm = adcs_vec3_norm(&rate);

    ms_output.rate_t_s = rate;
    ms_output.rate_norm_t_s = rate_norm;

    if (!isfinite(rate_norm)) {
        ms_output.mode = MS_FAULT;
        ms_output.rejects = ms_state.rejects;
        return;
    }

    if (rate_norm <= ms_config.max_slew_t_s) {
        /* Accepted: store current field, clear rejects, TRACK, publish rate */
        ms_state.previous_field_t = *ms_input.field_body_t;
        ms_state.rejects = 0U;
        ms_output.mode = MS_TRACK;
        ms_output.rejects = 0U;
        ms_output.accepted_field_t = *ms_input.field_body_t;
        return;
    }

    /* Rate exceeds max_slew: preserve history, increment rejects */
    ms_state.rejects += 1U;
    ms_output.rejects = ms_state.rejects;

    if (ms_state.rejects >= ms_config.max_rejects) {
        /* Rejection reaches limit: latched FAULT, do not accept current field */
        ms_output.mode = MS_FAULT;
        return;
    }

    ms_output.mode = MS_REJECT;
    ms_output.accepted_field_t = ms_state.previous_field_t;
    return;
}

